 state=n.get('/api/v1/lighttick/action-plans',headers=h).json()['data'];assert next(x for x in state['plans'] if x['id']==tid)['status']=='completed';facts=n.get('/api/v1/lighttick/action-plans/records?plan_id='+tid,headers=h).json()['data'];assert len(facts['records'])==1 and facts['records'][0]['actual_minutes']==5
 bob=n.post('/api/v1/auth/login',data={'appId':'lighttick','account':'bob@example.com','password':'Password1234','clientType':'app'}).json()['data'];other=n.get('/api/v1/lighttick/action-plans',headers={**h,'Authorization':'Bearer '+bob['accessToken']}).json()['data'];assert not any(x['id'] in [pid,tid] for x in other['plans'])
 page.evaluate('window.scrollTo(0,0)');page.screenshot(path=str(a.output/'actions-desktop.png'),full_page=True);page.set_viewport_size({'width':375,'height':900});page.evaluate('window.scrollTo(0,0)');expect(page.get_by_role('heading',name='共享行动',exact=True)).to_be_visible();assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(a.output/'actions-mobile.png'),full_page=False);assert not errors,errors
 (a.output/'result.json').write_text(json.dumps({'passed':True,'check_id':pid,'time_id':tid,'checks':['native_same_identity','unsubmitted_form_reload','other_owner_isolated','stale_revision_preserved','pause_resume','check_complete_reopen_retains_facts','lost_accepted_response_exact_replay_after_reload','no_duplicate_create','explicit_actual_minutes','native_reads_same_execution','mobile_no_overflow'],'native_scope':'canonical HTTP, not native device UI'},ensure_ascii=False,indent=2));n.dispose();c.close();b.close()
